package com.axiom.analysis;import com.axiom.analysis.correlation.ChangeRelevanceService;import com.axiom.domain.pipeline.FileCategory;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;class ChangeRelevanceServiceTest{@Test void scoresSpecificAndCounterEvidence(){var s=new ChangeRelevanceService();assertThat(s.analyze("DEPENDENCY_FAILURE",List.of(FileCategory.DEPENDENCY_MANIFEST),false,false).relevance()).isEqualTo("RELATED");assertThat(s.analyze("INFRASTRUCTURE_FAILURE",List.of(FileCategory.DOCUMENTATION),true,true).relevance()).isEqualTo("UNRELATED");}}
